SELECT  
WHERE r.tenant_id=#{tenant} AND r.id > #{q.after}
AND r.receipt_no=#{q.filters.receiptNo}
AND p.payment_no=#{q.filters.paymentNo}
AND o.order_no=#{q.filters.orderNo}
AND r.channel_code=#{q.filters.channelCode}
AND r.disposition=#{q.filters.disposition}
AND r.disposition != 'NORMAL'
AND r.created_at >= #{q.createdFrom} AND r.created_at < #{q.createdTo}
ORDER BY r.id ASC LIMIT #{q.fetchLimit}
